<script setup lang="ts">
import {ref,onMounted,defineAsyncComponent} from 'vue'
const DeviceManager=defineAsyncComponent(()=>import('./DeviceManager.vue'))
const deviceUser=ref<Record<string,any>|null>(null)
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>}>(),emit=defineEmits<{share:[id:string],usage:[id:string]}>()
const users=ref<Row[]>([]),groups=ref<Row[]>([]),services=ref<Row[]>([]),tab=ref('users'),editing=ref<Row|null>(null),removing=ref<Row|null>(null),error=ref(''),notice=ref(''),busy=ref(false)
async function reload(){[users.value,groups.value,services.value]=await Promise.all(['proxy-users','user-groups','live'].map(p=>props.api(p)))}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(()=>void run(reload))
function create(){editing.value=tab.value==='users'?{name:'',enabled:true,quota_gib:0,reset_strategy:'rolling_monthly',reset_day:new Date().getDate(),expires_at:new Date(Date.now()+30*86400000).toISOString().slice(0,10),group_ids:[],rotate_credentials:false,billing_mode:'both',multiplier_milli:1000,max_devices:0}:{name:'',user_ids:[],service_ids:[],version:0,max_devices:0}}
function edit(r:Row){editing.value=JSON.parse(JSON.stringify(r));if(tab.value==='users'){editing.value!.expires_at=r.expires_at.slice(0,10);editing.value!.quota_gib=Number(r.quota_bytes??0)/1073741824;editing.value!.reset_strategy=r.reset_strategy??'never'}}
function save(){const v=editing.value;if(!v)return;void run(async()=>{const body=tab.value==='users'?{name:v.name,version:v.version,billing_mode:v.billing_mode??'both',multiplier_milli:Number(v.multiplier_milli??1000),max_devices:Number(v.max_devices??0),enabled:v.enabled,expires_at:new Date(v.expires_at+'T23:59:59').toISOString(),group_ids:v.group_ids,rotate_credentials:!!v.rotate_credentials,quota_bytes:Math.round(Number(v.quota_gib??0)*1073741824),reset_strategy:v.reset_strategy??'never',...(v.reset_anchor_input?{reset_anchor_at:new Date(v.reset_anchor_input).toISOString()}:v.reset_day?{reset_day:Number(v.reset_day)}:{})}:{name:v.name,user_ids:v.user_ids,service_ids:v.service_ids,version:v.version,max_devices:Number(v.max_devices??0)};await props.api((tab.value==='users'?'proxy-users':'user-groups')+(v.id?'/'+v.id:''),v.id?'PUT':'POST',body);editing.value=null;notice.value='已保存。权限变化会自动同步到对应 VPS 的完整内核配置。';await reload()})}
function remove(){const v=removing.value;if(!v)return;void run(async()=>{if(v.action==='reset'){await props.api('proxy-users/'+v.id+'/reset-traffic','POST',{restart_cycle:!!v.restart_cycle})}else{await props.api((tab.value==='users'?'proxy-users':'user-groups')+'/'+v.id,'DELETE')};removing.value=null;notice.value=v.action==='reset'?'本期用量已重置，累计流量保留。':'已删除，权限撤销等待 Agent 下一次同步。';await reload()})}
</script>
<template><section class="panel publish-card"><div class="section-heading"><div><h2>用户与权限</h2><p class="form-note">SS / Snell 可与其他协议一起授权；共享密钥按入口计量，无法独立统计、限额或撤销某个用户的共享流量。</p><p class="muted">用户拥有独立凭据；用户组决定可以使用哪些协议。订阅随组权限自动更新。</p></div><button class="primary" @click="create">＋ {{tab==='users'?'添加用户':'添加用户组'}}</button></div><nav class="subnav"><button :class="['secondary',{active:tab==='users'}]" @click="tab='users'">用户 {{users.length}}</button><button :class="['secondary',{active:tab==='groups'}]" @click="tab='groups'">用户组 {{groups.length}}</button></nav><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status" class="notice">{{notice}}</p>
<div class="table-scroll"><table v-if="tab==='users'"><thead><tr><th>用户</th><th>用户组</th><th>有效期 / 状态</th><th>已用 / 分配</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.name}}</td><td>{{groups.filter(g=>u.group_ids?.includes(g.id)).map(g=>g.name).join('、')||'未分配权限'}}</td><td>{{new Date(u.expires_at).toLocaleDateString()}}<small class="block-muted">{{u.active?'有效':u.enabled?'已到期':'已停用'}}</small></td><td>{{(Number(u.used_bytes??0)/1073741824).toFixed(2)}} GiB / {{u.quota_bytes?(Number(u.quota_bytes)/1073741824).toFixed(2)+' GiB':'不限'}}<small class="block-muted">{{u.limited?'流量已耗尽':u.quota_bytes?'剩余 '+(Math.max(0,u.quota_bytes-u.used_bytes)/1073741824).toFixed(2)+' GiB':'无限流量'}}</small><small v-if="u.next_reset_at" class="block-muted">下次重置 {{new Date(u.next_reset_at).toLocaleString()}}</small></td><td class="row-actions"><button class="text-button" @click="edit(u)">编辑权限</button><button class="text-button" @click="u.effective_max_devices?deviceUser=u:emit('share',u.id)">分享订阅</button><button class="text-button" @click="deviceUser=u">设备 {{u.device_count??0}} / {{u.effective_max_devices||'不限'}}</button><button class="text-button" @click="emit('usage',u.id)">用量 / 访问</button><button class="text-button" @click="removing={...u,action:'reset'}">重置流量</button><button class="text-button danger" @click="removing=u">删除</button></td></tr></tbody></table><table v-else><thead><tr><th>用户组</th><th>成员</th><th>允许的协议</th><th>操作</th></tr></thead><tbody><tr v-for="g in groups" :key="g.id"><td>{{g.name}}</td><td>{{g.user_ids.length}} 位用户</td><td>{{g.service_ids.map((id:string)=>services.find(s=>s.id===id)?.name??'已移除').join('、')||'未授权'}}</td><td><button class="text-button" @click="edit(g)">编辑</button><button class="text-button danger" @click="removing=g">删除</button></td></tr></tbody></table></div><div v-if="!(tab==='users'?users:groups).length" class="console-empty">{{tab==='users'?'添加用户，选择用户组即可分配权限。':'先添加用户组，勾选允许使用的协议。'}}</div></section>
<div v-if="editing" class="modal-backdrop" @keydown.esc="editing=null"><form class="modal" role="dialog" aria-modal="true" aria-label="编辑用户权限" @submit.prevent="save"><div class="modal-heading"><h2>{{editing.id?'编辑':'添加'}}{{tab==='users'?'用户':'用户组'}}</h2><button type="button" class="secondary" @click="editing=null">关闭</button></div><div class="form-content"><p v-if="error" role="alert" class="error">{{error}}</p><div class="fields"><label>名称<input v-model="editing.name" required maxlength="100"></label><template v-if="tab==='users'"><label>有效期至<input v-model="editing.expires_at" type="date" required></label><label>流量额度（GiB，0 为不限）<input v-model.number="editing.quota_gib" type="number" min="0" max="1000000" step="0.01" required></label><label>用户计费方式<select v-model="editing.billing_mode"><option value="both">双向：上传 + 下载（默认）</option><option value="uplink">仅上传</option><option value="downlink">仅下载</option><option value="max">本周期累计上传 / 下载取大</option></select></label><label>计费倍率<select v-model.number="editing.multiplier_milli"><option :value="100">0.1 ×</option><option :value="500">0.5 ×</option><option :value="1000">1 ×（默认）</option><option :value="1500">1.5 ×</option><option :value="2000">2 ×</option><option :value="3000">3 ×</option></select><small>自定义倍率（千分之一单位，1000 = 1×）</small><input v-model.number="editing.multiplier_milli" type="number" min="1" max="100000" step="1"></label><label>设备上限（0 为不启用）<input v-model.number="editing.max_devices" type="number" min="0" max="20"><small>与用户组取最严格非零上限。开启后请使用设备专属订阅。</small></label><p class="form-note full-field">倍率与计费方向仅对保存后的新流量生效，保留已扣额度。上传/下载原始计数另外保留。设备上限控制独立设备凭据名额，不把来源 IP 数当成物理设备数。</p><label>流量重置周期<select v-model="editing.reset_strategy" aria-label="流量重置周期"><option value="rolling_monthly">每月设置日重置 · 北京时间</option><option value="never">不自动重置</option><option value="daily">每天 00:00 · 北京时间</option><option value="monthly">每月 1 日 · 北京时间</option></select></label><label v-if="editing.reset_strategy==='rolling_monthly'">每月重置日（1–31）<input v-model.number="editing.reset_day" type="number" min="1" max="31" placeholder="留空按原周期起点日期"></label><label v-if="editing.reset_strategy==='rolling_monthly'">自定义周期起点（可选）<input v-model="editing.reset_anchor_input" type="datetime-local"><small>留空保留当前周期；新用户从保存时开始。例如设置为 5 日，下月 5 日重置；月末取当月最后一天，后续仍按原设置日。</small></label><label class="check-label"><input v-model="editing.enabled" type="checkbox">允许使用代理</label><label v-if="editing.id" class="check-label"><input v-model="editing.rotate_credentials" type="checkbox">轮换此用户凭据</label></template></div>
<template v-if="tab==='users'"><h3>分配用户组</h3><div class="choice-list"><label v-for="g in groups" :key="g.id"><input v-model="editing.group_ids" type="checkbox" :value="g.id">{{g.name}} <small>{{g.service_ids.length}} 个协议</small></label></div><p v-if="!groups.length" class="muted">请先在用户组中选择允许使用的协议。</p></template><template v-else><label>组内用户设备上限（0 不增加限制）<input v-model.number="editing.max_devices" type="number" min="0" max="20"><small>取用户与所有所属组的最严格非零上限；开启后通用用户凭据被撤销，使用设备专属链接。</small></label><h3>允许使用的协议</h3><div class="choice-list"><label v-for="s in services.filter(s=>(s.managed_users||['shadowsocks','snell'].includes(s.kind))&&!s.delete_requested_at)" :key="s.id"><input v-model="editing.service_ids" type="checkbox" :value="s.id">{{s.name}} <small>{{s.kind}} · {{s.address}}:{{s.port}}</small></label></div><p class="muted">SS / Snell 共享密钥配置使用专用订阅，不提供独立用户撤销。其他协议默认按用户授权。</p><h3>组内用户</h3><div class="choice-list"><label v-for="u in users" :key="u.id"><input v-model="editing.user_ids" type="checkbox" :value="u.id">{{u.name}}</label></div></template></div><div class="modal-footer"><button type="button" class="secondary" @click="editing=null">取消</button><button class="primary" :disabled="busy">保存</button></div></form></div>
<div v-if="removing" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="删除权限资源"><div class="form-content"><h2>{{removing.action==='reset'?'重置本期用量':'删除'}} {{removing.name}}？</h2><p v-if="removing.action==='reset'">本期已用额度清零，累计用量与访问记录保留。符合其他权限条件的用户将恢复使用。</p><label v-if="removing.action==='reset'&&removing.reset_strategy==='rolling_monthly'" class="check-label"><input v-model="removing.restart_cycle" type="checkbox">同时从现在重新开始一个月周期</label><p v-else>{{tab==='users'?'同时删除此用户的全部订阅，撤销其服务端身份。':'删除组内授权，用户仍保留其他组的权限。'}}权限将在 Agent 下一次同步生效；离线 Agent 会按控制端失联超时停止服务。</p><p v-if="error" class="error" role="alert">{{error}}</p></div><div class="modal-footer"><button class="secondary" @click="removing=null">取消</button><button class="primary" :disabled="busy" @click="remove">{{removing.action==='reset'?'确认重置':'确认删除'}}</button></div></section></div><DeviceManager v-if="deviceUser" :user="deviceUser" :api="api" @close="deviceUser=null" @changed="reload"/></template>
